/* 
  Sky Express VA Color Palette (from actual logo)
  - Navy Blue: #1a365d (primary)
  - Magenta/Pink: #d63384 (accent)
  - White: #ffffff
*/

:root {
  --sky-navy: #1a365d;
  --sky-navy-light: #2c5282;
  --sky-pink: #d63384;
  --sky-pink-light: #e879a8;
  --sky-pink-pale: #fce7ef;
}

body {
  /* Clean modern font stack */
  font-family: 'Tahoma', 'Segoe UI', 'Arial', sans-serif;
  overflow: hidden;
  background-image: linear-gradient(to bottom right, var(--tw-gradient-stops));
  --tw-gradient-from: #f8fafc var(--tw-gradient-from-position);
  --tw-gradient-to: rgb(248 250 252 / 0) var(--tw-gradient-to-position);
  --tw-gradient-stops: var(--tw-gradient-from), var(--tw-gradient-to);
  --tw-gradient-to: rgb(253 242 248 / 0.3) var(--tw-gradient-to-position);
  font-size: 12px;
  --tw-text-opacity: 1;
  color: rgb(51 51 51 / var(--tw-text-opacity, 1));
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* Sky Express themed panel */

.legacy-panel {
  border-radius: 0.25rem;
  border-width: 1px;
  --tw-border-opacity: 1;
  border-color: rgb(229 231 235 / var(--tw-border-opacity, 1));
  --tw-bg-opacity: 1;
  background-color: rgb(255 255 255 / var(--tw-bg-opacity, 1));
  --tw-shadow: 0 1px 2px 0 rgb(0 0 0 / 0.05);
  --tw-shadow-colored: 0 1px 2px 0 var(--tw-shadow-color);
  box-shadow:
    var(--tw-ring-offset-shadow, 0 0 #0000), var(--tw-ring-shadow, 0 0 #0000), var(--tw-shadow);
}

/* Accent border panel */

.accent-panel {
  border-radius: 0.25rem;
  border-left-width: 4px;
  --tw-border-opacity: 1;
  border-left-color: rgb(236 72 153 / var(--tw-border-opacity, 1));
  --tw-bg-opacity: 1;
  background-color: rgb(255 255 255 / var(--tw-bg-opacity, 1));
  --tw-shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
  --tw-shadow-colored: 0 4px 6px -1px var(--tw-shadow-color), 0 2px 4px -2px var(--tw-shadow-color);
  box-shadow:
    var(--tw-ring-offset-shadow, 0 0 #0000), var(--tw-ring-shadow, 0 0 #0000), var(--tw-shadow);
}

/* Classic Status Bar Text */

.status-text {
  font-size: 11px;
  --tw-text-opacity: 1;
  color: rgb(68 68 68 / var(--tw-text-opacity, 1));
}

/* Standard Scrollbar with Sky Express colors */

::-webkit-scrollbar {
  width: 12px;
  background: #f8fafc;
  border-left: 1px solid #e2e8f0;
}

::-webkit-scrollbar-thumb {
  background: linear-gradient(to bottom, #1a365d, #2c5282);
  border-radius: 6px;
  border: 2px solid #f8fafc;
}

::-webkit-scrollbar-thumb:hover {
  background: linear-gradient(to bottom, #2c5282, #1a365d);
}

/* Simulating the "Inset" look for inputs */

.inset-box {
  border-radius: 0.25rem;
  border-width: 1px;
  --tw-border-opacity: 1;
  border-color: rgb(209 213 219 / var(--tw-border-opacity, 1));
  --tw-bg-opacity: 1;
